function openaiKey(model) {
  let m = String(model || '').toLowerCase().trim();
  if (OP[m]) return m;
  m = m.replace(/-\d{4}-\d{2}-\d{2}$/, '');
  if (OP[m]) return m;
  const base = m.replace(/-codex(-max|-mini|-spark)?$/, '');
  return OP[base] ? base : null;
}
function priceCodex(u, key) {
  const p = OP[key];
